import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('full lifecycle with charge ok, ship', async () => {
  const h = await createHost();
  assert.equal(await h.order('a'), null);
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.create('a'), ok);
  assert.equal((await h.create('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'draft', items: 0, charges: 0, refunds: 0 });
  assert.equal((await h.place('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.deepEqual(await h.addItem('a'), ok);
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.removeItem('a'), ok);
  assert.deepEqual(await h.place('a'), ok);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.ship('a')).ok, false);
  const eff = await h.pendingEffects();
  assert.equal(eff.length, 1);
  assert.equal(eff[0].from, 'a');
  assert.equal(eff[0].kind, 'payment.charge');
  assert.deepEqual(eff[0].data, { amount: 2 });
  await h.completeEffect(eff[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.deepEqual(await h.ship('a'), ok);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'shipped', items: 2, charges: 1, refunds: 0 });
  (h as any).__dispose?.();
});

