import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('full lifecycle with charge ok, ship', async () => {
  const h = await createHost();
  assert.equal(await h.order('a'), null);
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.create('a'), ok);
  assert.equal((await h.create('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'draft', items: 0, charges: 0, refunds: 0 });
  assert.equal((await h.place('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.deepEqual(await h.addItem('a'), ok);
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.removeItem('a'), ok);
  assert.deepEqual(await h.place('a'), ok);
  assert.equal((await h.ship('a')).ok, false);
  const eff = await h.pendingEffects();
  assert.equal(eff.length, 1);
  assert.equal(eff[0].from, 'a');
  assert.equal(eff[0].kind, 'payment.charge');
  assert.deepEqual(eff[0].data, { amount: 2 });
  await h.completeEffect(eff[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.deepEqual(await h.ship('a'), ok);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'shipped', items: 2, charges: 1, refunds: 0 });
  (h as any).__dispose?.();
});

test('failed charge, cancel paid refunds, cancel draft', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'declined', items: 1, charges: 1, refunds: 0 });
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.ship('a')).ok, false);
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.retryPayment('a'), ok);
  assert.equal((await h.retryPayment('a')).ok, false);
  const [e2] = await h.pendingEffects();
  assert.deepEqual(e2.data, { amount: 1 });
  assert.notEqual(e2.id, e.id);
  await h.completeEffect(e2.id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'failed', items: 1, charges: 2, refunds: 0 });
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);

  await h.create('d'); await h.addItem('d'); await h.place('d');
  assert.equal((await h.retryPayment('d')).ok, false);
  const [g] = await h.pendingEffects();
  await h.completeEffect(g.id, 'failed');
  await h.retryPayment('d');
  const [g2] = await h.pendingEffects();
  await h.completeEffect(g2.id, 'ok');
  assert.deepEqual(await h.order('d'), { status: 'paid', items: 1, charges: 2, refunds: 0 });
  assert.deepEqual(await h.cancel('d'), ok);
  assert.deepEqual(await h.order('d'), { status: 'cancelled', items: 1, charges: 2, refunds: 1 });
  const [r] = await h.pendingEffects();
  await h.completeEffect(r.id, 'ok');

  await h.create('b'); await h.addItem('b'); await h.place('b');
  const [f] = await h.pendingEffects();
  await h.completeEffect(f.id, 'ok');
  assert.deepEqual(await h.cancel('b'), ok);
  assert.deepEqual(await h.order('b'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  const pend = await h.pendingEffects();
  assert.equal(pend.length, 1);
  assert.equal(pend[0].kind, 'payment.refund');
  await h.completeEffect(pend[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('b'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });

  // cancel while placed: ok answer refunds, failed answer does not
  await h.create('e'); await h.addItem('e'); await h.place('e');
  assert.deepEqual(await h.cancel('e'), ok);
  assert.deepEqual(await h.order('e'), { status: 'cancelling', items: 1, charges: 1, refunds: 0 });
  for (const cmd of ['cancel', 'ship', 'addItem', 'removeItem', 'place', 'retryPayment', 'create'] as const)
    assert.equal((await h[cmd]('e')).ok, false, cmd);
  const [ce] = (await h.pendingEffects()).filter((x) => x.from === 'e');
  await h.completeEffect(ce.id, 'ok');
  assert.deepEqual(await h.order('e'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  const re = (await h.pendingEffects()).filter((x) => x.from === 'e');
  assert.equal(re.length, 1);
  assert.equal(re[0].kind, 'payment.refund');

  await h.create('f'); await h.addItem('f'); await h.place('f');
  assert.deepEqual(await h.cancel('f'), ok);
  const [cf] = (await h.pendingEffects()).filter((x) => x.from === 'f');
  await h.completeEffect(cf.id, 'failed');
  assert.deepEqual(await h.order('f'), { status: 'cancelled', items: 1, charges: 1, refunds: 0 });
  assert.equal((await h.pendingEffects()).filter((x) => x.from === 'f').length, 0);

  await h.create('c');
  assert.deepEqual(await h.cancel('c'), ok);
  assert.deepEqual(await h.order('c'), { status: 'cancelled', items: 0, charges: 0, refunds: 0 });
  assert.equal((await h.addItem('c')).ok, false);
  (h as any).__dispose?.();
});

